    "        detectZs(edges, eL, eR, eP2, invS, norS);\n"
    "        maxScore = max(invS, norS);\n"
    "        if (maxScore > 0.0) invertedZ = invS > norS;\n"
    "      }\n"
    "      {\n"
    "        vec4 eP2 = unpackEdges(loadEdge(pp + ivec2(0, -2)));\n"
    "        detectZs(edges.argb, eB.argb, eT.argb, eP2.argb, invS, norS);\n"
    "        float vertScore = max(invS, norS);\n"
    "        if (vertScore > maxScore) { maxScore = vertScore; horizontal = false; invertedZ = invS > norS; }\n"
    "      }\n"
    "      if (maxScore > 0.0) {\n"
    "#if CM_EXTRA_SHARPNESS\n"
    "        float quality = floor(clamp(4.0 - maxScore, 0.0, 3.0) + 0.5);\n"
    "#else\n"
    "        float quality = floor(clamp(4.0 - maxScore, 0.0, 3.0));\n"
    "#endif\n"
    "        vec2 stepRight = horizontal ? vec2(1.0, 0.0) : vec2(0.0, -1.0);\n"
    "        float lenL, lenR;\n"
    "        findZLineLengths(lenL, lenR, pp, horizontal, invertedZ, stepRight);\n"
    "        lenL -= quality; lenR -= quality;\n"
    "        if (lenL + lenR >= 5.0 && !collectZs(pp, horizontal, invertedZ, quality, lenL, lenR)) blendZs(pp, horizontal, invertedZ, quality, lenL, lenR, stepRight);\n"
    "      }\n"
    "    }\n"
    "  }\n"
    "  memoryBarrierShared();\n"
    "  barrier();\n"
    "  uint total = min(uint(SLM_ITEMS), blendItemCount);\n"
    "  uint loops = (total + 127u - gl_LocalInvocationID.x) / 128u;\n"
    "  for (uint lp = 0u; lp < loops; lp++) {\n"
    "    uvec2 v = blendItems[lp * 128u + gl_LocalInvocationID.x];\n"
    "    ivec2 start = ivec2(int(v.x >> 18), int(v.x & 0x3FFFu));\n"
    "    bool horizontal = ((v.y >> 31) & 1u) != 0u, inverted = ((v.y >> 30) & 1u) != 0u;\n"
    "    float stepIndex = float((v.y >> 20) & 0x3FFu) - 256.0, srcOffset = float((v.y >> 10) & 0x3FFu) - 256.0, lerpK = float(v.y & 0x3FFu) / 1023.0;\n"
    "    vec2 stepRight = horizontal ? vec2(1.0, 0.0) : vec2(0.0, -1.0), blendDir = horizontal ? vec2(0.0, -1.0) : vec2(-1.0, 0.0);\n"
    "    if (inverted) blendDir = -blendDir;\n"
    "    ivec2 pp = ivec2(vec2(start) + stepRight * stepIndex);\n"
    "    vec3 cc = loadSrc(pp), cf = loadSrc(ivec2(vec2(pp) + blendDir * srcOffset));\n"
    "    storeColor(pp, mix(cc, cf, lerpK), true);\n"
    "  }\n"
    "}\n"
    "#endif\n"
    "\n"
    "#ifdef K_APPLY\n"
    "layout(local_size_x = 4, local_size_y = 32) in;\n"
    "void main() {\n"
    "  uint num = ctl[3], cnd = gl_GlobalInvocationID.y, qoff = gl_LocalInvocationID.x;\n"
    "  if (cnd >= num) return;\n"
    "  uint pid = loc[cnd];\n"
    "  ivec2 quad = ivec2(int(pid >> 16), int(pid & 0xFFFFu));\n"
    "  ivec2 pp = quad * 2 + ivec2(int(qoff & 1u), int(qoff >> 1));\n"
    "  uint cih = heads[headAt(quad)];\n"
    "  vec4 acc = vec4(0.0);\n"
    "  for (uint i = 0u; cih != 0xFFFFFFFFu && i < 32u; i++) {\n"
    "    uint offXY = (cih >> 30) & 3u;\n"
    "    bool complexShape = ((cih >> 26) & 1u) != 0u;\n"
    "    uint at = cih & ((1u << 26) - 1u);\n"
    "    if (at >= uint(items.length())) break;\n"
    "    uvec2 val = items[at];\n"
    "    cih = val.x;\n"
    "    if (offXY == qoff) {\n"
    "      float w = 0.8 + (complexShape ? 1.0 : 0.0);\n"
    "      acc += vec4(unpackUnorm4x8(val.y).rgb * w, w);\n"
    "    }\n"
    "  }\n"
    "  if (acc.a == 0.0) return;\n"
    "  if (pp.x < sz.x && pp.y < sz.y) imageStore(outImg, pp, vec4(acc.rgb / acc.a, 1.0));\n"
    "}\n"
    "#endif\n";
